//
// ...quick and very minimal circle doodle
//
// genuary24 genuary2025
//
// prompt: "pick either a circle, rectangle, or triangle and use only that geometric shape"
//

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int NUM=20;
    vec3 col=vec3(0);
    for(int i=0;i<NUM;i++){
        float fi=float(i)/float(NUM-1);
        float r=(fi+.07)*iResolution.x*.5;
        vec2 p=r*.3*cos(fi*1.57*4.*4.*vec2(1,.7)+iTime*3.-vec2(0,1.57))+iResolution.xy*.5;
        vec3 ci=vec3(1.-fi)*(1.-step(0.,length(fragCoord-p)-r));
        col=max(col,ci);
    }
    fragColor=vec4(col,1);
}
